    n = len(src)
    j = i + 1
    if j >= n:
        return None
    kind = "start"
    if src[j] == "/":
        kind = "end"
        j += 1
    if j >= n or not (src[j].isalpha()):
        return None
    k = j
    while k < n and src[k] not in SPACE and src[k] not in "/>":
        k += 1
    name = src[j:k].lower()
