    p = k
    while True:
        ws_start = p
        while p < n and src[p] in SPACE:
            p += 1
        ws = src[ws_start:p]
        if p >= n:
            return (n, kind, name, parts, ws)
        if src[p] == ">":
            return (p + 1, kind, name, parts, ws)
        if src[p] == "/" and p + 1 < n and src[p + 1] == ">":
            return (p + 2, kind, name, parts, ws + "/")
        if src[p] == "/":
            p += 1
            parts.append((ws, "/", "", ""))
            continue
