        while p < n and src[p] not in SPACE and src[p] not in "=>":
            if src[p] == "/" and p + 1 < n and src[p + 1] == ">":
                break
            p += 1
        aname = src[a_start:p]
        if not aname:
            p += 1
            continue
        save = p
        while p < n and src[p] in SPACE:
            p += 1
        if p < n and src[p] == "=":
            p += 1
            while p < n and src[p] in SPACE:
                p += 1
