                    e = n - 1
                value = src[p + 1:e]
                p = e + 1
            else:
                v_start = p
                while p < n and src[p] not in SPACE and src[p] != ">":
                    p += 1
                value = src[v_start:p]
        else:
            p = save
            value = ""
        parts.append((ws, src[a_start:p], aname, value))
    # unreachable


def _find_raw_end(src, i, name):
    """Index of the '</name' that terminates a raw-text element."""
    pat = re.compile(r"</\s*" + re.escape(name) + r"(?=[\s/>])", re.IGNORECASE)
    m = pat.search(src, i)
    return m.start() if m else -1


def filter_html(src):
    out = []
    i = 0
    n = len(src)
    while i < n:
        lt = src.find("<", i)
        if lt == -1:
            out.append(src[i:])
            break
        out.append(src[i:lt])
        rest = src[lt:lt + 4]
        if rest.startswith("<!--"):
            end = src.find("-->", lt + 4)
            end = n if end == -1 else end + 3
            comment = src[lt:end]
