            end = src.find(">", lt + 2)
            end = n if end == -1 else end + 1
            out.append(src[lt:end])
            i = end
            continue

        parsed = _parse_tag(src, lt)
        if parsed is None:
            out.append("<")
            i = lt + 1
            continue
        end, kind, name, parts, tail = parsed

        if kind == "start" and name in RAW_TEXT:
            close = _find_raw_end(src, end, name)
            if close == -1:
                body, after = src[end:], n
                close_tag = ""
            else:
                gt = src.find(">", close)
                gt = n if gt == -1 else gt + 1
                body, close_tag, after = src[end:close], src[close:gt], gt
            if name == "script":
                i = after            # element and content removed entirely
                continue
            if name == "style":
                body = _sanitize_css(body)
            out.append(_render(name, kind, parts, tail))
            out.append(body)
            out.append(close_tag)
            i = after
            continue

        out.append(_render(name, kind, parts, tail))
        i = end
    return "".join(out)


def _render(name, kind, parts, tail):
    if kind == "end":
        pieces = ["</", name]
    else:
        pieces = ["<", name]
    for ws, raw, aname, avalue in parts:
        if aname and _drop_attr(name, aname, avalue):
            continue
        pieces.append(ws)
        pieces.append(raw)
    pieces.append(tail)
    pieces.append(">")
    return "".join(pieces)


def main(argv):
    if len(argv) < 2:
        sys.stderr.write("usage: filter.py <html-file>\n")
        return 2
    path = argv[1]
    with open(path, "rb") as fh:
        raw = fh.read()
    for enc in ("utf-8", "latin-1"):
        try:
            text = raw.decode(enc)
            break
        except UnicodeDecodeError:
            continue
    else:
        enc, text = "utf-8", raw.decode("utf-8", "replace")

    prev = None
    cleaned = text
    for _ in range(5):                # converge on nested/mangled payloads
        prev, cleaned = cleaned, filter_html(cleaned)
        if cleaned == prev:
            break

    with open(path, "wb") as fh:
        fh.write(cleaned.encode(enc, "replace"))
    return 0


if __name__ == "__main__":
    sys.exit(main(sys.argv))
